const post = $input.item.json;
const url = post.link ?? post.guid;
const publishedAt = post.isoDate ?? new Date().toISOString();
const html = post.content ?? post.summary ?? '';
if (!post.title || !url) throw new Error('Feed item needs title and link');
const source = {
  source_type: 'rss',
  source_external_id: $env.SOURCE_ID,
  source_name: $env.SOURCE_NAME,
  source_url: $env.SOURCE_URL,
  category: $env.SOURCE_CATEGORY ?? 'university',
};
if (!source.source_external_id || !source.source_name || !source.source_url) {
  throw new Error('SOURCE_ID, SOURCE_NAME, and SOURCE_URL are required');
}
return [{ json: {
  entity: 'news_items',
  organization_id: $env.APP_ORGANIZATION_ID,
  source,
  items: [{
    external_id: post.guid ?? url, title: post.title, summary: post.contentSnippet ?? post.content ?? null, published_at: publishedAt, original_url: url,
    news_blocks: [
      { type: '__article_introduction__', category_id: source.category, author: source.source_name, published_at: publishedAt, image_url: null, title: post.title },
      { type: '__html__', content: html }
    ], raw_data: post
  }]
} }];
